Lemma bsb_argv_prefix : forall ph (sp : word) av ev uid hw rnd, exists tail,
  build_stack_bytes ph sp av ev uid hw rnd =
    word_le8 (len_word av)
    ++ flat_map word_le8 (fst (string_addrs (cat_string_base sp av ev) av))
    ++ tail.
Proof.
